def edit_distance(source, target):
    # previous[j] is the distance between "" (or a shorter source prefix)
    # and the first j characters of target. The empty source costs j inserts.
    previous = list(range(len(target) + 1))

    for i, a in enumerate(source, 1):
        # Deleting i characters is the cost of turning this prefix into "".
        current = [i] + [0] * len(target)
        for j, b in enumerate(target, 1):
            if a == b:
                current[j] = previous[j - 1]          # free diagonal step
            else:
                current[j] = 1 + min(
                    previous[j - 1],                  # replace
                    previous[j],                      # delete from source
                    current[j - 1],                   # insert into source
                )
        previous = current

    return previous[len(target)]

