function editDistance(source, target) {
  // previous[j] = distance from a shorter source prefix to target[0..j).
  let previous = Array.from({ length: target.length + 1 }, (_, j) => j);

  for (let i = 1; i <= source.length; i += 1) {
    const current = new Array(target.length + 1).fill(0);
    current[0] = i; // deleting i characters gets this prefix to ""
    for (let j = 1; j <= target.length; j += 1) {
      current[j] = source[i - 1] === target[j - 1]
        ? previous[j - 1]                              // free diagonal step
        : 1 + Math.min(
            previous[j - 1],                           // replace
            previous[j],                               // delete from source
            current[j - 1],                            // insert into source
          );
    }
    previous = current;
  }

  return previous[target.length];
}

long long editDistance(std::string source, std::string target) {
    const std::size_t m = target.size();
    std::vector<long long> previous(m + 1), current(m + 1);

    // Empty source: j inserts to build the first j characters of target.
    for (std::size_t j = 0; j <= m; ++j) previous[j] = (long long)j;

    for (std::size_t i = 1; i <= source.size(); ++i) {
        current[0] = (long long)i;  // i deletes to reach ""
        for (std::size_t j = 1; j <= m; ++j) {
            if (source[i - 1] == target[j - 1]) {
                current[j] = previous[j - 1];            // free diagonal step
            } else {
                current[j] = 1 + std::min(previous[j - 1],          // replace
                                 std::min(previous[j],              // delete
                                          current[j - 1]));         // insert
            }
        }
        previous = current;
    }

    return previous[m];
}
